int main() {
    std::string name;
    std::cout << "What is your name? ";
    // getline reads the whole line, spaces included.
    std::getline(std::cin, name);
    std::cout << "\nHello, " << name << "!\n";

    int tickets;
    double price;
    std::cout << "How many tickets? ";
