    std::cout << "\nPrice per ticket? ";
    std::cin >> price;
    std::cout << "\n" << tickets << " tickets cost " << tickets * price << " euros\n";

    // After >>, the Enter key is still waiting: std::ws skips it.
    std::string film;
    std::cout << "Which film? ";
    std::getline(std::cin >> std::ws, film);
    std::cout << "\nEnjoy " << film << ", " << name << "!\n";

    // Several values on one line: >> skips the spaces between them.
    int row, seat;
    std::cout << "Row and seat? ";
    std::cin >> row >> seat;
    std::cout << "\nYour seat: row " << row << ", seat " << seat << '\n';
    return 0;
}

#include <iostream>

int main() {
    // Shipping cost in an online shop.
    double basket = 42.5;
    if (basket >= 50) {
        std::cout << "Free shipping\n";
    } else if (basket >= 30) {
        std::cout << "Basket " << basket << ": shipping 2.99\n";
    } else {
        std::cout << "Basket " << basket << ": shipping 5.99\n";
    }

    // The first true condition wins; the rest are skipped.
    int score = 78;
    char grade = 'F';
    if (score >= 90) grade = 'A';
    else if (score >= 75) grade = 'B';
    else if (score >= 50) grade = 'C';
    std::cout << "Score " << score << " -> grade " << grade << '\n';

    // switch compares one value with fixed cases; break ends each case.
    switch (grade) {
        case 'A': std::cout << "Excellent!\n"; break;
        case 'B': std::cout << "Very good\n"; break;
        case 'C': std::cout << "Passed\n"; break;
        default:  std::cout << "Try again\n";
    }

    // The ternary operator: condition ? if_true : if_false.
    int stock = 0;
    std::cout << (stock > 0 ? "In stock" : "Sold out") << '\n';
    return 0;
}

#include <iostream>
#include <string>

int main() {
    int age = 16;
    bool withAdult = true;
    double temperature = 31.5;

    // A comparison gives a bool: true or false.
    bool adult = age >= 18;
    std::cout << "adult = " << adult << '\n';  // by default, 0 or 1
    std::cout << std::boolalpha;               // from now on, false or true
    std::cout << "adult = " << adult << '\n';
    std::cout << "age == 16: " << (age == 16) << ", age != 16: " << (age != 16) << '\n';

    // && (and): both must be true. || (or): at least one. ! (not) reverses.
    bool canEnter = adult || withAdult;
    std::cout << "Can see the film: " << canEnter << '\n';
    bool hotDay = temperature > 30 && temperature <= 45;
    std::cout << "Hot day: " << hotDay << ", not hot: " << !hotDay << '\n';

    // Short-circuit: if the left side decides, the right one is not evaluated.
    int boxes = 0, items = 12;
    if (boxes != 0 && items / boxes > 5) std::cout << "The boxes are full\n";
    else std::cout << "No boxes to check (and no division by zero)\n";

    // Strings are compared in alphabetical order.
    std::string a = "apple", b = "banana";
    std::cout << a << " < " << b << ": " << (a < b) << '\n';
    return 0;
}

#include <iostream>

int main() {
    // while repeats the block as long as the condition is true.
    int savings = 0, months = 0;
    while (savings < 500) {
        savings += 120;
        months++;
    }
    std::cout << "Goal reached in " << months << " months: " << savings << " euros\n";

    // A countdown: seconds-- uses the value, then subtracts one.
    int seconds = 5;
    while (seconds > 0) std::cout << seconds-- << "... ";
    std::cout << "Lift off!\n";

    // do-while runs the block once before checking the condition.
    int energy = 0;
    do {
        std::cout << "The player gets one turn (energy " << energy << ")\n";
    } while (energy > 0);

    // break leaves the loop; continue jumps to the next round.
    int n = 0;
    while (true) {
        n++;
        if (n % 3 == 0) continue;  // skip multiples of 3
        if (n > 10) break;
        std::cout << n << ' ';
    }
    std::cout << '\n';
    return 0;
}

#include <iostream>
#include <string>

int main() {
    // for (start; condition; step): the classic counting loop.
    for (int i = 1; i <= 5; i++) {
        std::cout << "7 x " << i << " = " << 7 * i << '\n';
    }

    // Adding up inside a loop, in steps of 2.
    int sum = 0;
    for (int n = 2; n <= 100; n += 2) sum += n;
    std::cout << "2 + 4 + ... + 100 = " << sum << '\n';

    // Range-based for: goes through every element of a collection.
    double temps[] = {18.5, 21.0, 24.5, 19.0};
    double total = 0;
    for (double t : temps) total += t;
    std::cout << "Average temperature: " << total / 4 << '\n';

    // A string is a collection of characters.
    int vowels = 0;
    for (char c : std::string("programming"))
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') vowels++;
    std::cout << "Vowels in \"programming\": " << vowels << '\n';

    // Nested loops: a small multiplication grid.
    for (int row = 1; row <= 3; row++) {
        for (int col = 1; col <= 4; col++) std::cout << row * col << '\t';
        std::cout << '\n';
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

int main() {
    // A vector is a list that knows its size and can grow.
    std::vector<std::string> players = {"Ana", "Luis", "Marta"};
    std::vector<int> scores = {120, 95, 140};
    std::cout << "Players: " << players.size() << '\n';
    std::cout << "First: " << players[0] << ", last: " << players.back() << '\n';

    scores[1] = 110;  // [] also changes an element; positions start at 0

    // A for with an index, to use two vectors at the same time.
    for (std::size_t i = 0; i < players.size(); i++)
        std::cout << players[i] << ": " << scores[i] << " points\n";

    // push_back adds an element at the end.
    players.push_back("Pablo");
    scores.push_back(130);

    // A range-based for reads every value.
    int total = 0;
    for (int s : scores) total += s;
    std::cout << "Total: " << total << ", average: " << total / static_cast<double>(scores.size()) << '\n';

    // at() checks that the position exists; [] does not.
    std::cout << "Fourth player: " << players.at(3) << '\n';

    // A vector of 4 elements, all of them 3.
    std::vector<int> lives(4, 3);
    std::cout << "Lives of player 2: " << lives[1] << " (" << lives.size() << " players)\n";
    return 0;
}

#include <algorithm>
#include <functional>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> list = {"milk", "bread", "eggs"};
    list.push_back("apples");                 // at the end
    list.insert(list.begin(), "coffee");      // at the start
    list.insert(list.begin() + 2, "butter");  // before position 2
    for (auto item : list) std::cout << item << ' ';
    std::cout << "(" << list.size() << " items)\n";

    // erase removes by position (here, the second item); pop_back, the last one.
    list.erase(list.begin() + 1);
    list.pop_back();

    // sort from <algorithm> puts a range in order: begin() to end().
    std::sort(list.begin(), list.end());
    for (auto item : list) std::cout << item << ' ';
    std::cout << "(" << list.size() << " items)\n";

    // Game scores: lowest, highest and a top list from high to low.
    std::vector<int> scores = {450, 120, 899, 75, 300};
    std::cout << "Lowest: " << *std::min_element(scores.begin(), scores.end())
              << ", highest: " << *std::max_element(scores.begin(), scores.end()) << '\n';
    std::sort(scores.begin(), scores.end(), std::greater<int>());
    for (int s : scores) std::cout << s << ' ';
    list.clear();
    std::cout << "\nList empty? " << std::boolalpha << list.empty() << '\n';
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

// A function: return type, name, parameters and body.
double toFahrenheit(double celsius) { return celsius * 9 / 5 + 32; }

// void: it does something, but returns nothing.
void printLine(int width) {
    for (int i = 0; i < width; i++) std::cout << '-';
    std::cout << '\n';
}

// return ends the function as soon as it runs.
std::string describe(double celsius) {
    if (celsius < 10) return "cold";
    if (celsius < 25) return "mild";
    return "hot";
}

double average(std::vector<double> values) {
    double sum = 0;
    for (double v : values) sum += v;
    return values.empty() ? 0 : sum / values.size();
}

int main() {
    std::vector<double> week = {8.5, 14.0, 22.5, 27.0, 31.5};
    printLine(26);
    for (double c : week) std::cout << c << " C = " << toFahrenheit(c) << " F, " << describe(c) << '\n';
    printLine(26);
    std::cout << "Average: " << average(week) << " C, " << describe(average(week)) << '\n';
    return 0;
}

#include <iostream>
#include <vector>

// By value: the function gets a copy, so the original does not change.
void addBonusCopy(int points) { points += 50; std::cout << "Inside the copy:     " << points << '\n'; }

// By reference (&): the function works on the original variable.
void addBonus(int& points) { points += 50; }

// const reference: no copy and no changes. Ideal for strings and vectors.
double total(const std::vector<double>& prices) {
    double sum = 0;
    for (double p : prices) sum += p;
    return sum;
}

int main() {
    int score = 100;
    addBonusCopy(score);
    std::cout << "After the copy:      " << score << '\n';
    addBonus(score);
    std::cout << "After the reference: " << score << '\n';

    int& alias = score;  // a reference: another name for the same variable
    alias = 0;
    std::cout << "alias = 0, so score is now " << score << '\n';

    // In a for, & changes each element in place: a 10% discount.
    std::vector<double> basket = {20.0, 12.5, 7.5};
    for (double& p : basket) p *= 0.9;
    for (const double& p : basket) std::cout << p << ' ';
    std::cout << "\nTotal after discount: " << total(basket) << '\n';
    return 0;
}

#include <iostream>
#include <string>

// Default arguments: used when the call leaves them out.
double withVat(double price, double vat = 0.21) { return price * (1 + vat); }

void greet(const std::string& name, const std::string& word = "Hello", int times = 1) {
    for (int i = 0; i < times; i++) std::cout << word << ", " << name << "! ";
    std::cout << '\n';
}

// Overloading: the same name with different parameters.
double area(double side) { return side * side; }                     // a square
double area(double width, double height) { return width * height; }  // a rectangle

void show(int value) { std::cout << "int: " << value << '\n'; }
void show(double value) { std::cout << "double: " << value << '\n'; }
void show(const std::string& text) { std::cout << "string: \"" << text << "\"\n"; }

int main() {
    std::cout << "Shoes: " << withVat(100) << '\n';        // vat = 0.21
    std::cout << "Book:  " << withVat(100, 0.04) << '\n';  // vat = 0.04

    greet("Carmen");
    greet("Carmen", "Good morning");
    greet("Leo", "Hi", 3);

    // The compiler picks the version that matches the arguments.
    std::cout << "Square 4 m: " << area(4) << " m2, room 3 x 5 m: " << area(3, 5) << " m2\n";
    show(42);
    show(3.5);
    show("ready");
    return 0;
}

#include <iostream>
#include <map>
#include <string>

int main() {
    // A map links keys to values, and keeps the keys in order.
    std::map<std::string, int> stock = {{"pears", 5}, {"apples", 12}, {"plums", 0}};
    std::cout << "Apples: " << stock["apples"] << '\n';

    // [] changes a value, or creates the key if it is new.
    stock["pears"] = 8;
    stock["kiwis"] = 20;

    // count() checks a key without creating it (0 or 1).
    if (stock.count("bananas") == 0) std::cout << "No bananas today\n";

    // erase() removes a key together with its value.
    stock.erase("plums");

    // Each element is a pair: first is the key and second, the value.
    int pieces = 0;
    for (const auto& item : stock) {
        std::cout << item.first << ": " << item.second << '\n';
        pieces += item.second;
    }
    std::cout << stock.size() << " fruits, " << pieces << " pieces\n";

    // Counting is a classic job: a missing key starts at 0.
    std::map<char, int> letters;
    for (char c : std::string("banana")) letters[c]++;
    for (const auto& item : letters) std::cout << item.first << '=' << item.second << ' ';
    std::cout << '\n';
    return 0;
}

