// A function can return two results inside a pair.
std::pair<int, int> minMax(const std::vector<int>& values) {
    int lo = values[0], hi = values[0];
    for (int v : values) {
        if (v < lo) lo = v;
        if (v > hi) hi = v;
    }
    return {lo, hi};
}

int main() {
    // A pair holds two values, which may have different types.
    std::pair<std::string, double> product = {"Headphones", 59.99};
    std::cout << product.first << " cost " << product.second << " euros\n";

    auto city = std::make_pair("Valencia", 26);  // make_pair deduces the types
    std::cout << city.first << ": " << city.second << " C\n";

    // Structured bindings give a name to each part.
    std::vector<int> week = {19, 24, 17, 28, 22};
    auto [coldest, hottest] = minMax(week);
    std::cout << "This week: from " << coldest << " to " << hottest << " C\n";

    // They are very handy to go through a map.
    std::map<std::string, int> goals = {{"Lola", 7}, {"Iker", 12}, {"Sara", 9}};
    for (const auto& [player, count] : goals) std::cout << player << " scored " << count << '\n';
    return 0;
}

#include <iomanip>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

int main() {
    std::vector<std::pair<std::string, double>> menu = {
        {"Coffee", 1.5}, {"Croissant", 2.25}, {"Orange juice", 3}, {"Toast", 1.8}};

    // setw sets the width of the NEXT value; left and right align it.
    std::cout << std::left << std::setw(14) << "Item" << std::right << std::setw(8) << "Price" << '\n';
    // setfill changes the character that fills the gap.
    std::cout << std::setfill('-') << std::setw(22) << "" << std::setfill(' ') << '\n';

    // fixed + setprecision(2): always two decimals, until changed.
    std::cout << std::fixed << std::setprecision(2);
    double total = 0;
    for (const auto& [name, price] : menu) {
        std::cout << std::left << std::setw(14) << name << std::right << std::setw(8) << price << '\n';
        total += price;
    }
    std::cout << std::left << std::setw(14) << "TOTAL" << std::right << std::setw(8) << total << '\n';

    // Leading zeros for an order number.
    std::cout << "Order #" << std::setfill('0') << std::setw(5) << 42 << std::setfill(' ') << '\n';

    // Without fixed, setprecision counts significant digits.
    std::cout << std::defaultfloat << std::setprecision(3) << "Pi is about " << 3.14159 << '\n';

    // Integers in other bases.
    std::cout << "255 in hex: " << std::hex << 255 << ", in octal: " << std::oct << 255 << std::dec << '\n';
    return 0;
}

#include <iostream>
#include <stdexcept>
#include <string>
