// throw stops the function and sends an error to whoever called it.
double withdraw(double balance, double amount) {
    if (amount <= 0) throw std::invalid_argument("the amount must be positive");
    if (amount > balance) throw std::runtime_error("not enough money");
    return balance - amount;
}

int main() {
    double balance = 100;
    std::vector<double> requests = {30, -5, 200, 50};
    for (double amount : requests) {
        try {  // try runs the code; the first matching catch handles the error
            balance = withdraw(balance, amount);
            std::cout << "Withdrew " << amount << ", balance " << balance << '\n';
        } catch (const std::invalid_argument& e) {
            std::cout << "Invalid request " << amount << ": " << e.what() << '\n';
        } catch (const std::runtime_error& e) {
            std::cout << "Refused " << amount << ": " << e.what() << '\n';
        }
    }

    // The library throws too: std::stoi with text that is not a number.
    try {
        std::cout << std::stoi("twenty") << '\n';
    } catch (const std::exception&) {  // std::exception catches any standard error
        std::cout << "\"twenty\" is not a number, but the program goes on\n";
    }
    return 0;
}

#include <fstream>
#include <iostream>
#include <string>

int main() {
    // ofstream writes a file in the current folder (it creates or empties it).
    std::ofstream out("temperatures.txt");
    out << "Madrid 24.5\n" << "Bilbao 17.5\n" << "Sevilla 31.2\n";
    out.close();

    // std::ios::app adds at the end instead of starting again.
    std::ofstream more("temperatures.txt", std::ios::app);
    more << "Valencia 26.8\n";
    more.close();

    // ifstream reads it; always check that it could be opened.
    std::ifstream in("temperatures.txt");
    if (!in) { std::cout << "Could not open the file\n"; return 1; }

    // >> reads word by word, just like std::cin, until the end of the file.
    std::string city, hottestCity;
    double temp, hottest = -100;
    int count = 0;
    while (in >> city >> temp) {
        std::cout << city << ": " << temp << " C\n";
        if (temp > hottest) { hottest = temp; hottestCity = city; }
        count++;
    }
    std::cout << count << " cities, the hottest is " << hottestCity << " (" << hottest << " C)\n";
    return 0;
}

