    }
};

void writeLog(const std::string& data) { std::cout << "  [log] " << data << "\n"; }
struct Cart {
    int items = 0;
    void add(const std::string& p) { std::cout << "  [cart] " << p << ", " << ++items << " item(s)\n"; }
};

int main() {
    EventBus bus; Cart cart; int clicks = 0;
    bus.on("click", [&clicks](const std::string& button) { std::cout << "  [ui] click " << ++clicks << ": " << button << "\n"; });
    bus.on("click", writeLog);                                  // a plain function fits too
    bus.on("add", [&cart](const std::string& p) { cart.add(p); });   // calls a method
    bus.emit("click", "Buy now");
    bus.emit("add", "Headphones");
    bus.emit("add", "Charger");
    bus.emit("close", "nobody listens");                        // no handlers: nothing runs
}

#include <array>
#include <iostream>
#include <type_traits>

// constexpr: the compiler can work it out while compiling, if the inputs are known.
constexpr unsigned long long mebibytes(unsigned long long n) { return n * 1024 * 1024; }
constexpr int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
constexpr std::array<int, 10> makeSquares() {      // a table built at compile time
    std::array<int, 10> t{};
    for (int i = 0; i < 10; ++i) t[i] = i * i;
    return t;
}
constexpr auto squares = makeSquares();
constexpr int width = 1920, height = 1080;
constexpr unsigned long long cacheSize = mebibytes(64);
// static_assert: a check done by the compiler. If it fails, nothing compiles.
static_assert(width * 9 == height * 16, "the screen must be 16:9");
static_assert(cacheSize == 67108864, "64 MiB in bytes");
static_assert(squares[7] == 49 && sizeof(long long) >= 8);

template <typename T>
void describe(T value) {           // if constexpr: only the matching branch is compiled
    if constexpr (std::is_integral_v<T>) std::cout << value << " is a whole number\n";
    else std::cout << value << " is not a whole number\n";
}

int main() {
    constexpr int g = gcd(width, height);
    std::cout << "Aspect ratio " << width / g << ":" << height / g << ", cache " << cacheSize << " bytes\n";
    std::cout << "Square of 7 from the table: " << squares[7] << "\n";
    int n = 84;                    // known only at run time: the same function still works
    std::cout << "gcd(" << n << ", 36) = " << gcd(n, 36) << "\n";
    describe(42); describe(2.5);
}

#include <algorithm>
#include <iostream>
#include <memory>
#include <vector>

struct Shape {                     // the interface every shape on the canvas follows
    const char* name;
    explicit Shape(const char* n) : name(n) {}
    virtual ~Shape() = default;
    virtual double area() const = 0;
};
struct Circle : Shape {
    double r;
    Circle(const char* n, double r) : Shape(n), r(r) {}
    double area() const override { return 3.14159 * r * r; }
};
struct Rect : Shape {
    double w, h;
    Rect(const char* n, double w, double h) : Shape(n), w(w), h(h) {}
    double area() const override { return w * h; }
};

int main() {
    std::vector<std::unique_ptr<Shape>> canvas;      // the canvas owns its shapes
    canvas.push_back(std::make_unique<Rect>("banner", 6, 2.5));
    canvas.push_back(std::make_unique<Circle>("logo", 1.5));
    canvas.push_back(std::make_unique<Rect>("dot", 0.5, 0.4));
    canvas.push_back(std::make_unique<Rect>("button", 3, 1));
    canvas.erase(std::remove_if(canvas.begin(), canvas.end(), [](const auto& s) { return s->area() < 1; }), canvas.end());
    std::sort(canvas.begin(), canvas.end(), [](const auto& a, const auto& b) { return a->area() > b->area(); });
    double total = 0;
    for (const auto& s : canvas) { total += s->area(); std::cout << s->name << ": " << s->area() << "\n"; }
    std::cout << canvas.size() << " shapes, total area " << total << "\n";
}
